"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["99165"],{5165(e){e.exports=JSON.parse('{"id":"F115","slug":"platform-cost-comparison","name":"Investment Platform Cost Comparison","subject":"Personal Finance","section":"Personal Finance","topic":"Choosing a broker or investment platform","level":"Beginner","aliases":["choosing a broker","broker fees","platform fee","flat fee vs percentage fee"],"formula":{"latex":"\\\\text{Cost}=T\\\\,f\\\\,n+p\\\\,B_{0}\\\\,\\\\frac{(1+g)^{n}-1}{g},\\\\quad B^{*}=\\\\frac{T(f_{A}-f_{B})}{p_{B}-p_{A}}","also":[],"text":"Total cost over n years = trades per year x fee per trade x years + percentage fee x starting balance x ((1 + growth)^n - 1) / growth (percentage fee charged on the balance at the start of each year); Break-even balance = trades x (fee A - fee B) / (percentage B - percentage A)"},"symbols":[{"symbol":"T","meaning":"Trades per year","unit":"count"},{"symbol":"f","meaning":"Fee per trade","unit":"money"},{"symbol":"p","meaning":"Percentage platform fee on the balance","unit":"per year"},{"symbol":"B_0","meaning":"Starting balance","unit":"money"},{"symbol":"g","meaning":"Assumed growth of the balance","unit":"per year"}],"when_to_use":"Use it to compare two platforms with different fee structures. A flat fee per trade favors large balances and few trades, while a percentage fee favors small balances. The break-even balance shows where the choice flips. Also compare fund costs, currency conversion fees and the range of investments available, which this does not include.","worked_example":{"problem":"A balance of 40,000 grows 5% a year for 10 years and you make 12 trades a year. Platform A charges nothing per trade but 0.35% a year. Platform B charges 5 per trade and 0.05% a year.","inputs":{"bal":40000,"t":12,"fa":0,"pa":0.35,"fb":5,"pb":0.05,"g":5,"n":10},"steps":[{"label":"Sum of year-start balances / starting balance = ((1 + g)^n - 1) / g","working":"((1+0.05)^10-1) / 0.05","value":"12.578"},{"label":"Platform A total cost","working":"12 x 0 x 10+0.0035 x 40000 x 12.5779","value":"1,760.90"},{"label":"Platform B total cost","working":"12 x 5 x 10+0.0005 x 40000 x 12.5779","value":"851.56"},{"label":"Difference (A - B)","working":"1760.9-851.558","value":"909.35"},{"label":"Cheaper platform (1 = A, 2 = B)","working":"1 if 1760.9<=851.558 else 2","value":"2"},{"label":"Break-even balance (year-one view) = trades x (fee A - fee B) / (pct B - pct A)","working":"12 x (0-5) / (0.0005-0.0035)","value":"20,000.00"}],"answer":"Over 10 years platform A costs 1,760.90 and platform B costs 851.56, so A minus B is 909.35 (a negative number means A is cheaper). The break-even balance is 20,000.00: above it the flat-fee platform wins, and below it the percentage-fee one does."},"calculator":{"available":true,"inputs":[{"id":"bal","label":"Starting balance","unit":"money","type":"number","default":40000,"hint":""},{"id":"t","label":"Trades per year","unit":"count","type":"number","default":12,"hint":""},{"id":"fa","label":"Platform A fee per trade","unit":"money","type":"number","default":0,"hint":""},{"id":"pa","label":"Platform A percentage fee","unit":"%","type":"number","default":0.35,"hint":""},{"id":"fb","label":"Platform B fee per trade","unit":"money","type":"number","default":5,"hint":""},{"id":"pb","label":"Platform B percentage fee","unit":"%","type":"number","default":0.05,"hint":""},{"id":"g","label":"Assumed growth of the balance","unit":"%","type":"number","default":5,"hint":""},{"id":"n","label":"Years","unit":"years","type":"number","default":10,"hint":"","min":1}],"checks":[{"expr":"bal>0 and g>0 and pa!=pb","message":"The balance and growth must be above zero, and the two percentage fees must differ."}],"steps":[{"id":"fac","label":"Sum of year-start balances / starting balance = ((1 + g)^n - 1) / g","expr":"((1+g)^n-1)/g","format":"num3"},{"id":"ca","label":"Platform A total cost","expr":"t*fa*n+pa*bal*fac","format":"money"},{"id":"cb","label":"Platform B total cost","expr":"t*fb*n+pb*bal*fac","format":"money"},{"id":"diff","label":"Difference (A - B)","expr":"ca-cb","format":"money"},{"id":"cheaper_","label":"Cheaper platform (1 = A, 2 = B)","expr":"1 if ca<=cb else 2","format":"num0"},{"id":"be","label":"Break-even balance (year-one view) = trades x (fee A - fee B) / (pct B - pct A)","expr":"t*(fa-fb)/(pb-pa)","format":"money"}],"results":["ca","cb","be"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"fac":12.57789253554884,"ca":1760.9049549768374,"cb":851.5578507109768,"diff":909.3471042658606,"cheaper_":2,"be":20000}},"finder":{"finds":"Which platform costs less over a holding period","needs":"Balance, trading frequency, each platform\'s fees"},"related":[{"slug":"fee-drag","name":"Cost of Fees: Active vs. Passive"},{"slug":"tracking-difference","name":"Index Fund Tracking Difference and Error"},{"slug":"cost-of-trade-credit","name":"Cost of Skipping an Early-Payment Discount"}],"related_ids":["F244","F114","F194"],"group":"Personal finance","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Cost</mtext><mo>=</mo><mi>T</mi><mtext>\u2009</mtext><mi>f</mi><mtext>\u2009</mtext><mi>n</mi><mo>+</mo><mi>p</mi><mtext>\u2009</mtext><msub><mi>B</mi><mn>0</mn></msub><mtext>\u2009</mtext><mfrac><mrow><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><mi>g</mi><msup><mo stretchy=\\"false\\">)</mo><mi>n</mi></msup><mo>\u2212</mo><mn>1</mn></mrow><mi>g</mi></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><msup><mi>B</mi><mo lspace=\\"0em\\" rspace=\\"0em\\">\u2217</mo></msup><mo>=</mo><mfrac><mrow><mi>T</mi><mo stretchy=\\"false\\">(</mo><msub><mi>f</mi><mi>A</mi></msub><mo>\u2212</mo><msub><mi>f</mi><mi>B</mi></msub><mo stretchy=\\"false\\">)</mo></mrow><mrow><msub><mi>p</mi><mi>B</mi></msub><mo>\u2212</mo><msub><mi>p</mi><mi>A</mi></msub></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Cost}=T\\\\,f\\\\,n+p\\\\,B_{0}\\\\,\\\\frac{(1+g)^{n}-1}{g},\\\\quad B^{*}=\\\\frac{T(f_{A}-f_{B})}{p_{B}-p_{A}}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"change-in-nwc","name":"Investment in Net Working Capital (Projects)"},"next":{"slug":"thesis-expected-return-margin","name":"Investment Thesis: Expected Return and Margin of Safety"},"lesson":null,"total":522}')}}]);